class Solution:
    def totalScore(self, hp: int, damage: List[int], requirement: List[int]) -> int:
        d = 0
        ans = 0
        for i, (dm, rq) in enumerate(zip(damage, requirement)):
            d += dm
            if hp - d >= rq:
                ans += i + 1
        return ans

