class Solution:
    def totalScore(self, hp: int, damage: List[int], requirement: List[int]) -> int:
        n = len(damage)
        D = list(itertools.accumulate(damage))
        good = [hp - D[i] >= requirement[i] for i in range(n)]
        S = [0] * (n + 1)
        for j in range(n - 1, -1, -1):
            S[j] = S[j+1] + good[j]
        return sum(S[:n])

