        int n = damage.size();
        vector<long long> D(n);
        partial_sum(damage.begin(), damage.end(), D.begin());
        vector<int> S(n + 1, 0);
        for (int j = n - 1; j >= 0; j--)
            S[j] = S[j+1] + (hp - D[j] >= requirement[j]);
        long long ans = 0;
        for (int j = 0; j < n; j++) ans += S[j];
        return ans;
    }
};

