class Solution {
    public long totalScore(int hp, int[] damage, int[] requirement) {
        int n = damage.length;
        long[] D = new long[n];
        for (int i = 0; i < n; i++) D[i] = (i ? D[i-1] : 0) + damage[i];
        long[] S = new long[n + 1];
        for (int j = n - 1; j >= 0; j--)
            S[j] = S[j+1] + (hp - D[j] >= requirement[j] ? 1 : 0);
        long ans = 0;
        for (int j = 0; j < n; j++) ans += S[j];
        return ans;
    }
}

